{
  "story": "During K-means iteration, each point is assigned to its nearest centroid. Then, centroids move to the exact mean position of their assigned points, minimizing variance.",
  "aha": {
    "stateId": "step-2",
    "observation": "Centroids shift toward the center of their assigned point clusters after assignment."
  },
  "layout": {
    "preset": "card",
    "width": 640
  },
  "parts": [
    {
      "id": "rail",
      "kind": "step-rail",
      "bind": {
        "active": "inputs.stepIndex",
        "items": "variant.states"
      }
    },
    {
      "id": "picture",
      "kind": "fixed-picture",
      "bind": {
        "active": "inputs.stepIndex",
        "regions": "variant.regions",
        "target": "state.calloutRegion"
      }
    },
    {
      "id": "callout",
      "kind": "active-callout",
      "bind": {
        "reason": "state.why",
        "target": "state.calloutRegion",
        "text": "state.sentence"
      }
    },
    {
      "id": "readout",
      "kind": "value-readout",
      "bind": {
        "values": "state.readouts"
      }
    }
  ],
  "controls": [
    {
      "id": "stepIndex",
      "kind": "index",
      "label": "Iteration Step",
      "options": [
        "Init",
        "Assign",
        "Update"
      ]
    },
    {
      "id": "resetBtn",
      "kind": "reset",
      "label": "Reset",
      "options": []
    }
  ],
  "data": {
    "variants": [
      {
        "label": "K-means Iteration",
        "regions": [
          {
            "id": "c1",
            "label": "Centroid A",
            "kind": "centroid",
            "values": ["2.0", "3.0"]
          },
          {
            "id": "c2",
            "label": "Centroid B",
            "kind": "centroid",
            "values": ["7.0", "8.0"]
          }
        ],
        "states": [
          {
            "id": "step-0",
            "label": "Initialize",
            "short": "Init",
            "sentence": "Initial random centroids are placed on the plane.",
            "why": "Starting point for clustering.",
            "active": ["c1", "c2"],
            "calloutRegion": "c1",
            "readouts": [
              {
                "id": "r1",
                "label": "Shift A",
                "value": "0.0"
              }
            ]
          },
          {
            "id": "step-1",
            "label": "Assign Points",
            "short": "Assign",
            "sentence": "Every data point is assigned to its nearest centroid.",
            "why": "Defines membership clusters.",
            "active": ["c1", "c2"],
            "calloutRegion": "c2",
            "readouts": [
              {
                "id": "r1",
                "label": "Shift A",
                "value": "0.5"
              }
            ]
          },
          {
            "id": "step-2",
            "label": "Update Centroids",
            "short": "Update",
            "sentence": "Centroids move to the mean position of their assigned points.",
            "why": "Reduces within-cluster scatter.",
            "active": ["c1", "c2"],
            "calloutRegion": "c1",
            "readouts": [
              {
                "id": "r1",
                "label": "Shift A",
                "value": "2.3"
              }
            ]
          }
        ]
      }
    ]
  }
}
